local CandelabraMaker = {}
local PRODUCTS = {
    iron_candelabra = { name = "Železni svečnik", ironCost = 2, waxCost = 1, time = 3, cost = 35, lightRadius = 20, prestige = 2, description = "Železni svečnik za mizo." },
    brass_candelabra = { name = "Medeninast svečnik", brassCost = 2, waxCost = 1, time = 4, cost = 75, lightRadius = 30, prestige = 4, happiness = 1, description = "Medeninast svečnik za dvorane." },
    silver_candelabra = { name = "Srebrni svečnik", silverCost = 2, waxCost = 1, time = 6, cost = 180, lightRadius = 40, prestige = 8, happiness = 2, description = "Srebrni svečnik za plemiče." },
    silver_branch_candelabra = { name = "Srebrnorogasti svečnik", silverCost = 2, goldCost = 1, waxCost = 1, time = 9, cost = 420, lightRadius = 50, prestige = 14, happiness = 3, description = "Svečnik z vejami za plemiče." },
    gold_trim_candelabra = { name = "Zlatorobni svečnik", goldCost = 1, silverCost = 1, jewelCost = 1, waxCost = 1, time = 12, cost = 900, lightRadius = 60, prestige = 22, happiness = 5, description = "Zlatorobni svečnik z draguljem." },
    royal_grand_candelabra = { name = "Kraljevski veliki svečnik", goldCost = 2, silverCost = 1, jewelCost = 1, pearlCost = 1, waxCost = 2, time = 17, cost = 2000, lightRadius = 75, prestige = 45, happiness = 10, description = "Veliki kraljevski svečnik z zlatom in dragulji za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Svečniška delavnica", cost = { gold = 280, wood = 130, stone = 250 }, upkeep = 7, qualityBonus = 5 },
    forge = { name = "Svečniška kovačija", cost = { gold = 950, wood = 250, stone = 450, iron = 8 }, upkeep = 23, qualityBonus = 18 },
    finishing_room = { name = "Dokončevalnica", cost = { gold = 2300, wood = 350, stone = 700, silver = 30, brass = 8 }, upkeep = 58, qualityBonus = 30 },
    royal_candelabra_atelier = { name = "Kraljevski atelje svečnikov", cost = { gold = 9200, wood = 600, stone = 1000, gold = 60, jewel = 20 }, upkeep = 185, qualityBonus = 55, prestigeBonus = 40 },
}
CandelabraMaker.ironStock = 14; CandelabraMaker.brassStock = 10; CandelabraMaker.silverStock = 8; CandelabraMaker.goldStock = 6; CandelabraMaker.waxStock = 12; CandelabraMaker.jewelStock = 6; CandelabraMaker.pearlStock = 4
CandelabraMaker.productStock = {}; CandelabraMaker.buildings = {}; CandelabraMaker.maker = nil; CandelabraMaker.activeMaking = {}; CandelabraMaker.totalProducts = 0; CandelabraMaker.dayTimer = 0
function CandelabraMaker.init() CandelabraMaker.ironStock=14; CandelabraMaker.brassStock=10; CandelabraMaker.silverStock=8; CandelabraMaker.goldStock=6; CandelabraMaker.waxStock=12; CandelabraMaker.jewelStock=6; CandelabraMaker.pearlStock=4; CandelabraMaker.productStock={}; CandelabraMaker.buildings={}; CandelabraMaker.maker=nil; CandelabraMaker.activeMaking={}; CandelabraMaker.totalProducts=0; CandelabraMaker.dayTimer=0; print("[CandelabraMaker] Royal Candelabra Maker System initialized (6 products, 4 buildings)") end
function CandelabraMaker.hireMaker(n,s) s=s or math.random(50,90); local c=520+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; CandelabraMaker.maker={name=n or ("Svečničar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Svečničar najet: %s (spretnost: %d)",CandelabraMaker.maker.name,s),"success") end; return true end
function CandelabraMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function CandelabraMaker.build(id) local ok,e=CandelabraMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(CandelabraMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function CandelabraMaker.getQualityBonus() local b=0; for _,bd in ipairs(CandelabraMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function CandelabraMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and CandelabraMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.brassCost and CandelabraMaker.brassStock<(d.brassCost or 0) then return false,"Premalo medenine" end; if d.silverCost and CandelabraMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and CandelabraMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.waxCost and CandelabraMaker.waxStock<(d.waxCost or 0) then return false,"Premalo voska" end; if d.jewelCost and CandelabraMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and CandelabraMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #CandelabraMaker.buildings==0 then return false,"Potrebna delavnica" end; if not CandelabraMaker.maker then return false,"Potreben svečničar" end; return true end
function CandelabraMaker.make(pt,qty) qty=qty or 1; local ok,e=CandelabraMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then CandelabraMaker.ironStock=CandelabraMaker.ironStock-d.ironCost*qty end; if d.brassCost then CandelabraMaker.brassStock=CandelabraMaker.brassStock-d.brassCost*qty end; if d.silverCost then CandelabraMaker.silverStock=CandelabraMaker.silverStock-d.silverCost*qty end; if d.goldCost then CandelabraMaker.goldStock=CandelabraMaker.goldStock-d.goldCost*qty end; if d.waxCost then CandelabraMaker.waxStock=CandelabraMaker.waxStock-d.waxCost*qty end; if d.jewelCost then CandelabraMaker.jewelStock=CandelabraMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then CandelabraMaker.pearlStock=CandelabraMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if CandelabraMaker.maker then t=math.max(1,t-math.floor(CandelabraMaker.maker.skill/12)) end; table.insert(CandelabraMaker.activeMaking,{id="candelabra_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,lightRadius=d.lightRadius or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function CandelabraMaker.completeMaking(m) local q=1.0+(CandelabraMaker.getQualityBonus()/100); if CandelabraMaker.maker then q=q+(CandelabraMaker.maker.skill/180) end; q=math.min(2.0,q); CandelabraMaker.productStock[m.productType]=(CandelabraMaker.productStock[m.productType] or 0)+m.quantity; CandelabraMaker.totalProducts=CandelabraMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if CandelabraMaker.maker then CandelabraMaker.maker.itemsMade=CandelabraMaker.maker.itemsMade+m.quantity; if math.random()<0.20 then CandelabraMaker.maker.skill=math.min(100,CandelabraMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Svečnik izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"candelabra.completed",{productName=m.productName,lightRadius=m.lightRadius,prestige=m.prestige,happiness=m.happiness}) end end
function CandelabraMaker.update(dt) if not _G.state then return end; CandelabraMaker.dayTimer=CandelabraMaker.dayTimer+dt; if CandelabraMaker.dayTimer>=30 then CandelabraMaker.dayTimer=0; for i=#CandelabraMaker.activeMaking,1,-1 do local m=CandelabraMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then CandelabraMaker.completeMaking(m); table.remove(CandelabraMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(CandelabraMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if CandelabraMaker.maker then tu=tu+14 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function CandelabraMaker.getStats() return {ironStock=CandelabraMaker.ironStock,brassStock=CandelabraMaker.brassStock,silverStock=CandelabraMaker.silverStock,goldStock=CandelabraMaker.goldStock,waxStock=CandelabraMaker.waxStock,jewelStock=CandelabraMaker.jewelStock,pearlStock=CandelabraMaker.pearlStock,productStock=CandelabraMaker.productStock,numBuildings=#CandelabraMaker.buildings,hasMaker=CandelabraMaker.maker~=nil,makerName=CandelabraMaker.maker and CandelabraMaker.maker.name or "—",makerSkill=CandelabraMaker.maker and CandelabraMaker.maker.skill or 0,activeMaking=#CandelabraMaker.activeMaking,totalProducts=CandelabraMaker.totalProducts} end
return CandelabraMaker
